    if extra.strip():
        exec(extra, {'db': db, 'collection': collection, 'ObjectId': ObjectId, 'datetime': datetime})

    # Execute student's answer (the query)
    result = execute_mongodb_query(db, collection, student_answer)

    # Execute test code to get expected result (if provided)
    if testcode.strip():
