                                    else:
                                        expected = "Test to pass"
                                        got = f"Test failed: {reason}"
                                else:
                                    expected = "Test to pass"
                                    got = "Test failed with no error message"

                            testresults.append([test_code, expected, got])
        except (json.JSONDecodeError, KeyError, TypeError):
            continue

    if total > 0:
        fraction = passed / total
        output = {
            "fraction": fraction,
            "testresults": testresults
        }
        print(json.dumps(output))
    else:
        combined_output = (result.stdout or "") + "\n" + (result.stderr or "")
        print(f"***Error: No test results found.\n\nForge output:\n{combined_output.strip() or 'No output'}\n\nExit code: {result.returncode}")
        sys.exit(1)

finally:
    os.chdir('/')
    shutil.rmtree(temp_dir, ignore_errors=True)

